import '../application-drawer.scss'
const emit=defineEmits<{saved:[id:number];submitted:[id:number];progress:[id:number];closed:[]}>()
const user=useUserStore(),workspace=useCollaborationWorkspace(),router=useRouter(),options=ref<api.MoldOptions>()
const busy=ref(false),error=ref('')
const controls=computed(()=>options.value?.controls.filter(c=>!['DDPhotoField','DDAttachment'].includes(c.type)&&!['generatedCodes','informationComplete'].includes(c.key))||[])
async function attempt(action:()=>Promise<unknown>){const auth=user.token;try{await action()}catch(e){if(auth!==user.token||e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'操作失败，请核对后重试';ElMessage.error(error.value)}}
type EditorDraft=api.MoldApplication|api.MoldResearchContext
const projectInputUnsaved=ref(false)
const editor=ref(false),editing=ref<EditorDraft>(),form=reactive<Record<string,string|null>>({}),phoneCodeItemId=ref<number|null>(null),productLineId=ref<number|null>(null)
const researchSource=computed(()=>editing.value?.sourceSnapshot?.research);
const submissionPolicy=computed(()=>editing.value?.submissionPolicy);
const researchSubmission=computed(()=>submissionPolicy.value?.mode==='research'&&submissionPolicy.value.requiresCodes===false&&submissionPolicy.value.requiresTipoMapping===false);
const requiresCodes=computed(()=>!researchSubmission.value);
const requiresStandardPhone=computed(()=>!researchSubmission.value||submissionPolicy.value?.requiresStandardPhone!==false);
const filingMissing=computed(()=>researchSubmission.value?submissionPolicy.value?.filingMissing||[]:[]);
const existingApplicationNotice=computed(()=>editing.value&&'existingApplicationNotice' in editing.value?editing.value.existingApplicationNotice:'');
const sourceAttachments=ref<Record<number,AttachmentVO>>({}),sourceAttachmentErrors=ref<Record<number,string>>({});
const sourceViewer=useAttachmentViewer();
let sourceFilesEpoch=0,phoneRestoreEpoch=0;
async function loadSourceFiles(row?:EditorDraft){
  const epoch=++sourceFilesEpoch,auth=user.token;sourceAttachments.value={};sourceAttachmentErrors.value={};
  if(!row||row.applicationId||row.sourceSnapshot?.research?.restricted)return;
  await Promise.all((row.sourceSnapshot?.research?.references||[]).filter(file=>file.type==='file').map(async file=>{
    try{const attachment=await getAttachmentDetail(file.id);if(epoch!==sourceFilesEpoch||auth!==user.token)return;if(attachment.attachmentId!==file.id||file.checksum&&attachment.checksum!==file.checksum)throw new Error('来源文件版本不匹配，请重新核对');sourceAttachments.value[file.id]=attachment;}
    catch(error){if(epoch===sourceFilesEpoch&&auth===user.token)sourceAttachmentErrors.value[file.id]=error instanceof Error?error.message:'来源文件读取失败，请重试';}
  }));
}
watch(editing,row=>void loadSourceFiles(row));
watch(editor,active=>{if(!active){invalidatePhoneRestore();++sourceFilesEpoch;sourceAttachments.value={};sourceAttachmentErrors.value={};}});
const supplierRoles:Record<string,string>={mold:'模具',component:'部件',processing:'加工',finished_product:'成品供货'};
const executionReason=ref(''),newApplication=ref(false),draftRequestId=ref(''),sourceRequestId=crypto.randomUUID()
const executionIntent=ref<api.MoldExecutionIntent>('new'),targetItemId=ref<number|null>(null),targetMoldSetId=ref<number|null>(null),targetProjectId=ref<number|null>(null),targets=ref<api.MoldTargetOptions>({projects:[],items:[]})
const uploading=ref(false)
const standardPhoneIds=ref<number[]>([]),standardPhone=ref<CompatiblePhone>(),compatibleMolds=ref<PhoneCompatibleMold[]>([]),reuseSetId=ref<number|null>(null)
const currentPhoneCodes=computed(()=>standardPhone.value?.codeItemId?[{codeItemId:standardPhone.value.codeItemId,codeValue:standardPhone.value.phoneModelCode || '',codeName:standardPhone.value.modelName,status:standardPhone.value.codeStatus || 'enabled'}]:editing.value?.phoneCodeItemId?[{codeItemId:editing.value.phoneCodeItemId,codeValue:editing.value.originalPhoneModelCode || editing.value.phoneModelCode || '原编码待核实',codeName:editing.value.model || '历史引用',status:'enabled'}]:[])
const reuseSelection=computed(()=>compatibleMolds.value.find(row=>row.moldSetId===reuseSetId.value))
const eligibleProductIds=computed(()=>new Set(options.value?.productLines.filter(p=>p.moldApplicationEligibility?.eligible===true).map(p=>p.productId)))
const productChoices=computed(()=>options.value?.productLines.filter(p=>eligibleProductIds.value.has(p.productId)||p.productId===productLineId.value)||[])
const productSelectionIssue=computed(()=>{const line=productLineId.value;if(line&&!eligibleProductIds.value.has(line)){const p=options.value?.productLines.find(p=>p.productId===line);return p?.moldApplicationEligibility?.reason||'产品开模资格尚未读取，请刷新后核对；历史草稿保留。'}const config=options.value?.configs.find(c=>c.tipo===form.tipo);if(config&&!eligibleProductIds.value.has(config.productLineId))return options.value?.productLines.find(p=>p.productId===config.productLineId)?.moldApplicationEligibility?.reason||'原 Tipo 对应产品当前不能新开模，请核对产品资格。';return ''})
const tipoControl=computed(()=>controls.value.find(c=>c.key==='tipo'))
const inputControls=computed(()=>controls.value.filter(c=>c.key!=='tipo'))
const mappedTypes=computed(()=>options.value?.configs.filter(c=>c.productLineId===productLineId.value&&controls.value.some(control=>control.key==='tipo'&&control.options.includes(c.tipo)))||[])
const selectedProduct=computed(()=>options.value?.productLines.find(product=>product.productId===productLineId.value));
const productIdentityMissing=computed(()=>!!researchSource.value&&!!selectedProduct.value&&!selectedProduct.value.productSpecificCode?.trim());
const canMaintainProductIdentity=computed(()=>selectedProduct.value?.canMaintainProductIdentity===true);
const productIdentityIssue=computed(()=>productIdentityMissing.value&&requiresCodes.value?'尚未维护本产品的两位产品特定编码；可先保存草稿，填写已确认编码后再预留或提交。':'');
const configurationMissing=computed(()=>!researchSubmission.value&&!!productLineId.value&&eligibleProductIds.value.has(productLineId.value)&&!mappedTypes.value.length)
const configurationIssue=computed(()=>{if(!productLineId.value||productSelectionIssue.value)return '';if(researchSubmission.value)return form.tipo&&tipoSelectable(form.tipo)?'':tipoChoices.value.length?'请核对并选择与当前新品对应的钉钉审批类型。':'当前钉钉模板没有可用于此新品的审批类型，请审批管理员核对模板；不自动新增选项。';if(configurationMissing.value)return '尚未配置本产品在当前钉钉审批中的 Tipo 与 PLM 产品线映射；可先保存草稿，补齐配置后再预留编码或提交。';if(!mappedTypes.value.some(c=>c.tipo===form.tipo))return '请选择与本产品对应的当前审批 Tipo，再预留编码或提交。';return ''})
const executionIssue=computed(()=>productSelectionIssue.value||productIdentityIssue.value||configurationIssue.value)
function productLabel(p:api.MoldOptions['productLines'][number]){return p.productName+(p.moldApplicationEligibility?.kind==='research'?' · 新品研发':p.salesStatus==='off_sale'?' · 已停售':p.moldApplicationEligibility?.eligible?'':' · 暂不可申请')}
const currentResearchTipos=computed(()=>researchSubmission.value?(submissionPolicy.value?.allowedTipos||[]).filter(tipo=>tipoControl.value?.options.includes(tipo)):[]);
function tipoSelectable(tipo:string){if(researchSubmission.value)return currentResearchTipos.value.includes(tipo);const c=options.value?.configs.find(c=>c.tipo===tipo);return !!c&&c.productLineId===productLineId.value&&eligibleProductIds.value.has(c.productLineId)}
const tipoChoices=computed(()=>[...new Set([...(researchSubmission.value?currentResearchTipos.value:mappedTypes.value.map(c=>c.tipo)),...(form.tipo?[form.tipo]:[])])])
const automaticTipo=computed(()=>!!productLineId.value&&eligibleProductIds.value.has(productLineId.value)&&mappedTypes.value.length===1&&mappedTypes.value[0]?.tipo===form.tipo&&tipoSelectable(form.tipo))
function chooseProduct(){if(researchSubmission.value){if(form.tipo&&tipoSelectable(form.tipo))return;const mapped=mappedTypes.value.length===1?mappedTypes.value[0]?.tipo:null;form.tipo=mapped&&currentResearchTipos.value.includes(mapped)?mapped:null;return;}const current=options.value?.configs.find(c=>c.tipo===form.tipo);if(current?.productLineId===productLineId.value)return;const choices=options.value?.configs.filter(c=>c.productLineId===productLineId.value&&controls.value.find(control=>control.key==='tipo')?.options.includes(c.tipo))||[];form.tipo=choices.length===1?choices[0]!.tipo:null}
let optionsEpoch=0
async function refreshOptions(){const epoch=++optionsEpoch,auth=user.token;try{const value=await api.getMoldOptions();if(epoch===optionsEpoch&&auth===user.token&&editor.value){options.value=value;if(!form.tipo)chooseProduct()}}catch(e){if(epoch===optionsEpoch&&auth===user.token&&editor.value)error.value=e instanceof Error?e.message:'产品开模资格刷新失败，请重试'}}
function openMaintenance(path:string,query:Record<string,string>){if(busy.value||uploading.value)return;const destination=router.resolve({path,query});window.open(destination.href,'_blank','noopener,noreferrer')}
function openConfiguration(){if(!options.value?.administrator||!productLineId.value)return;openMaintenance('/mold-applications',{configure:'1',productLineId:String(productLineId.value)})}
function openProductIdentity(){const source=researchSource.value,step=selectedProduct.value?.researchStepNo||source?.currentStepNo;if(!source||!canMaintainProductIdentity.value||!step)return;openMaintenance(`/products/${source.projectId}/edit`,{source:'research',step:launchStage(step).key})}
function refreshOnFocus(){if(editor.value&&!busy.value&&!uploading.value)void refreshOptions()}
watch(()=>workspace.revision,()=>{if(editor.value)void refreshOptions()})
let compatibilityEpoch=0
async function loadCompatibility(){const epoch=++compatibilityEpoch,auth=user.token;compatibleMolds.value=[];reuseSetId.value=null;if(!standardPhone.value||!productLineId.value)return;try{const rows=await getPhoneCompatibleMolds(standardPhone.value.phoneModelId,productLineId.value);if(epoch===compatibilityEpoch&&auth===user.token)compatibleMolds.value=rows}catch{if(epoch===compatibilityEpoch&&auth===user.token)error.value='已确认共模关系读取失败，请重试核对'}}
function chooseStandardPhone(rows:CompatiblePhone[]){if(rows.length>1){standardPhoneIds.value=standardPhone.value?[standardPhone.value.phoneModelId]:[];ElMessage.warning('一次开模申请请选择一款标准手机；兼容组在模具详情维护');return}invalidatePhoneRestore();standardPhone.value=rows[0];form.model=rows[0]?phoneMemberName(rows[0]):null;phoneCodeItemId.value=rows[0]?.codeItemId||null;void loadCompatibility();void loadTargets()}
let targetsEpoch=0
async function loadTargets(){const epoch=++targetsEpoch;targets.value={projects:[],items:[]};if(!standardPhone.value||!productLineId.value)return;const auth=user.token;try{const value=await api.getMoldTargetOptions(standardPhone.value.phoneModelId,productLineId.value);if(epoch===targetsEpoch&&auth===user.token)targets.value=value}catch(e){if(epoch===targetsEpoch&&auth===user.token)error.value=e instanceof Error?e.message:'建档目标读取失败，请重试'}}
watch(productLineId,()=>{void loadCompatibility();void loadTargets()})
watch(executionIntent,value=>{if(value==='new'){targetItemId.value=null;targetMoldSetId.value=null}})
const departmentId=ref<number>()
watch(()=>options.value?.submitter,who=>{if(who?.departments.some(department=>department.id===departmentId.value))return;departmentId.value=who?.departments.length===1?who.departments[0]!.id:undefined})
const failedUploads=ref<{selectionId:string;category:string;file:File;registered:boolean}[]>([])
const filesComplete=computed(()=>!failedUploads.value.length&&!(editing.value?.files||[]).some(f=>f.downloadStatus!=='downloaded'))
const generated=computed(()=>editing.value?.generatedCodes||(researchSubmission.value?'待工程建档时确认，不影响新品审批':'尚未生成'))
const submissionMissing=computed(()=>{if(!researchSubmission.value)return [];const missing=controls.value.filter(control=>control.required&&!String(form[control.key]||'').trim()).map(control=>control.label);const deliveryLabel=controls.value.find(control=>control.key==='expectedDeliveryDate')?.label||'期望交付时间';if(!form.expectedDeliveryDate?.trim()&&!missing.includes(deliveryLabel))missing.push(deliveryLabel);if(!(editing.value?.files||[]).some(file=>file.category==='key_photo'&&file.downloadStatus==='downloaded'))missing.push('关键图片');return missing;})
const unsaved=computed(()=>!editing.value||controls.value.some(c=>String(form[c.key]||'')!==String(editing.value?.form[c.key]||''))||phoneCodeItemId.value!==editing.value.phoneCodeItemId||productLineId.value!==editing.value.productLineId||reuseSelection.value?.compatibilityDigest!==editing.value.reservedCompatibility?.compatibilityDigest||standardPhoneIds.value[0]!== (editing.value.phoneModelId||undefined)||executionIntent.value!==(editing.value.executionIntent||'new')||targetItemId.value!==(editing.value.targetItemId||null)||targetProjectId.value!==(editing.value.targetProjectId||null)||executionReason.value!==(editing.value.executionReason||'')||newApplication.value!==!!editing.value.newApplication)
const dirty=computed(()=>unsaved.value&&(!!editing.value||Object.values(form).some(Boolean)||!!standardPhoneIds.value.length||!!productLineId.value||!!executionReason.value.trim()))
function invalidatePhoneRestore(){++phoneRestoreEpoch;++compatibilityEpoch;++targetsEpoch}
function edit(row?:EditorDraft){invalidatePhoneRestore();editing.value=row;draftRequestId.value=crypto.randomUUID();executionReason.value=row?.executionReason||'';newApplication.value=!!row?.newApplication;failedUploads.value=[];standardPhoneIds.value=[];standardPhone.value=undefined;compatibleMolds.value=[];reuseSetId.value=null;++compatibilityEpoch;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,row?.form||{});phoneCodeItemId.value=row?.phoneCodeItemId||null;productLineId.value=row?.productLineId||null;executionIntent.value=row?.executionIntent||'new';targetItemId.value=row?.targetItemId||null;targetMoldSetId.value=row?.targetMoldSetId||null;targetProjectId.value=row?.targetProjectId||null;targets.value={projects:[],items:[]};editor.value=true}
async function restorePhone(row?:EditorDraft){
  const epoch=++phoneRestoreEpoch,phoneId=row?.phoneModelId||row?.reservedCompatibility?.phoneModelId;
  if(!row||!phoneId||!editor.value)return;
  const auth=user.token,current=()=>epoch===phoneRestoreEpoch&&auth===user.token&&editor.value&&editing.value===row;
  try{
    const phones=await getPhoneModelOptions([phoneId]);if(!current())return;
    standardPhoneIds.value=[phoneId];standardPhone.value=phones[0];
    await Promise.all([loadCompatibility(),loadTargets()]);
    if(current()&&row.reservedCompatibility){compatibleMolds.value=[row.reservedCompatibility];reuseSetId.value=row.reservedCompatibility.moldSetId}
  }catch{if(current())error.value='标准手机资料读取失败，请核对后继续'}
}
watch(editing,row=>void restorePhone(row))
async function openExisting(id:number){if(busy.value||uploading.value)return;if(unsaved.value){try{await ElMessageBox.confirm('当前未保存的编辑将放弃，打开已有申请继续处理。','继续已有申请')}catch{return}}const token=user.token,row=await api.getMoldApplication(id);if(token!==user.token)return;if(row.status==='draft'&&row.canEditDraft!==false){edit(row);emit('saved',row.applicationId)}else{editor.value=false;emit('progress',row.applicationId)}}
function checkSession(auth:string){if(auth!==user.token)throw new Error('登录身份已变化，请重新打开申请')}
async function save(){
  const auth=user.token;
  if(busy.value)throw new Error('申请正在保存，请等待完成');
  if(!options.value?.canCreate||editing.value&&editing.value.status!=='draft')throw new Error('此申请已冻结或当前账号无编辑权限');
  if(productSelectionIssue.value&&(!editing.value||productLineId.value!==editing.value.productLineId||form.tipo!==editing.value.form.tipo))throw new Error(productSelectionIssue.value);
  const input:api.MoldDraftInput={form:{...form},productLineId:productLineId.value,phoneCodeItemId:phoneCodeItemId.value,version:editing.value?.applicationId?editing.value.version:undefined,phoneModelId:standardPhoneIds.value[0]||null,executionIntent:reuseSelection.value?'reuse':executionIntent.value,targetItemId:reuseSelection.value?.itemId||targetItemId.value,targetMoldSetId:reuseSelection.value?.moldSetId||targetMoldSetId.value,targetProjectId:targetProjectId.value,executionReason:executionReason.value.trim()||null,newApplication:newApplication.value,draftRequestId:draftRequestId.value||sourceRequestId};
  busy.value=true;
  try{
    const source=researchSource.value;
    const row=!editing.value?.applicationId&&source
      ?await api.startResearchMoldApplication({projectId:source.projectId,version:source.workflowVersion,phoneModelId:input.phoneModelId||null,requestId:input.draftRequestId!,draft:input})
      :await api.saveMoldApplication(editing.value?.applicationId||null,input);
    checkSession(auth);
    if(!row.applicationId)throw new Error('申请未返回记录编号，请刷新核对后重试');
    const latest=await api.getMoldApplication(row.applicationId);checkSession(auth);
    if(latest.status!=='draft'||latest.canEditDraft===false){editor.value=false;emit('progress',latest.applicationId);throw new Error('已有申请已提交或当前无编辑权限，请查看审批进度');}
    if(row.alreadyExists){const pending=failedUploads.value;edit(latest);failedUploads.value=pending;}else editing.value=latest;
    workspace.changed();ElMessage.success(row.alreadyExists?'已继续原申请草稿，保留原填写内容':'草稿已保存');emit('saved',latest.applicationId);return latest;
  }finally{busy.value=false}
}
async function reserve(){if(executionIssue.value)throw new Error(executionIssue.value);const auth=user.token;if(standardPhone.value&&(!standardPhone.value.codeItemId||standardPhone.value.codeLinkStatus!=='linked')){ElMessage.warning('标准手机编码尚待核对，不自动分配新编码');return}const selected=reuseSelection.value;const row=await save();checkSession(auth);busy.value=true;try{if(selected)await api.reserveMoldCodes(row.applicationId,row.version,{phoneModelId:selected.phoneModelId,itemId:selected.itemId,moldSetId:selected.moldSetId,compatibilityDigest:selected.compatibilityDigest});else if(standardPhone.value)await api.reserveMoldCodes(row.applicationId,row.version,{phoneModelId:standardPhone.value.phoneModelId});else await api.reserveMoldCodes(row.applicationId,row.version);checkSession(auth);const latest=await api.getMoldApplication(row.applicationId);checkSession(auth);editing.value=latest;phoneCodeItemId.value=editing.value.phoneCodeItemId;productLineId.value=editing.value.productLineId;ElMessage.success(selected?'已确认复用原PC/TPU刻码，未生成新模具':'编码已预留');emit('saved',editing.value!.applicationId)}finally{busy.value=false}}
async function uploadPending(){const auth=user.token;if(!failedUploads.value.length)return;uploading.value=true;try{const row=!editing.value?.applicationId||unsaved.value?await save():editing.value;checkSession(auth);const selected=await api.selectMoldFiles(row.applicationId,failedUploads.value.map(p=>({selectionId:p.selectionId,category:p.category,fileName:p.file.name,fileSize:p.file.size,contentType:p.file.type||'application/octet-stream'})));checkSession(auth);editing.value=selected;failedUploads.value.forEach(p=>p.registered=true);for(const pending of [...failedUploads.value]){try{checkSession(auth);const uploaded=await api.uploadMoldFile(row.applicationId,pending.category,pending.file,pending.selectionId);checkSession(auth);editing.value=uploaded;failedUploads.value=failedUploads.value.filter(f=>f!==pending)}catch(e){checkSession(auth);error.value=e instanceof Error?e.message:'文件上传失败'}}if(failedUploads.value.length)ElMessage.error('仍有文件上传失败；请重试或明确移除，暂不能提交审批');else ElMessage.success('所选文件已完整归档')}finally{uploading.value=false}}
async function upload(event:Event,category:string){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);if(!files.length)return;for(const file of files){const existing=editing.value?.files?.find(f=>f.downloadStatus==='pending_upload'&&f.category===category&&f.fileName===file.name&&f.fileSize===file.size);const selectionId=existing?.selectionId||crypto.randomUUID();failedUploads.value=failedUploads.value.filter(p=>p.selectionId!==selectionId);failedUploads.value.push({selectionId,category,file,registered:!!existing})}input.value='';await attempt(uploadPending)}
async function discardStored(f:api.MoldFile){if(!editing.value?.applicationId)return;editing.value=await api.discardMoldSelection(editing.value.applicationId,f.attachmentId);failedUploads.value=failedUploads.value.filter(p=>p.selectionId!==f.selectionId)}
async function discardPending(selectionId:string){if(editing.value?.applicationId){editing.value=await api.getMoldApplication(editing.value.applicationId);const f=editing.value.files?.find(f=>f.selectionId===selectionId);if(f)await discardStored(f)}failedUploads.value=failedUploads.value.filter(p=>p.selectionId!==selectionId)}
async function closeEditor(done:()=>void){if(busy.value||uploading.value)return;if(failedUploads.value.length||dirty.value){try{await ElMessageBox.confirm(failedUploads.value.length?'关闭将清除本次重试队列；已登记的未完成文件仍保留在草稿中，需重新上传或明确移除后才能提交。':'当前填写内容尚未保存，关闭将放弃这些修改。','关闭填写窗口？')}catch{return}}invalidatePhoneRestore();done();emit('closed')}
onBeforeRouteLeave(async()=>{if(!editor.value)return true;if(busy.value||uploading.value)return false;if(!dirty.value&&!failedUploads.value.some(p=>!p.registered))return true;try{await ElMessageBox.confirm('当前申请或文件选择尚未保存，离开将放弃未保存内容。','离开页面？');return true}catch{return false}})
const protectUnload=(e:BeforeUnloadEvent)=>{if(failedUploads.value.some(p=>!p.registered)){e.preventDefault();e.returnValue=''}}
onMounted(()=>{window.addEventListener('beforeunload',protectUnload);window.addEventListener('focus',refreshOnFocus)});onBeforeUnmount(()=>{invalidatePhoneRestore();++sourceFilesEpoch;window.removeEventListener('beforeunload',protectUnload);window.removeEventListener('focus',refreshOnFocus)})
async function submit(){if(!editing.value?.applicationId||busy.value||uploading.value||!options.value?.canSubmit)return;if(executionIssue.value)throw new Error(executionIssue.value);if(requiresStandardPhone.value&&!standardPhone.value){ElMessage.warning('请选择标准手机型号，保证申请与模具资料连贯');return}if(submissionMissing.value.length){ElMessage.warning(`送审还缺：${submissionMissing.value.join('、')}`);return}if((executionIntent.value==='new_set'||newApplication.value)&&!executionReason.value.trim()){ElMessage.warning('新增套或重新开模必须填写原因');return}if(executionIntent.value==='new_set'&&!targetItemId.value){ElMessage.warning('请选择加开一套所属的已有模具主档');return}if(!researchSubmission.value&&targets.value.projects.length&&!targetProjectId.value){ElMessage.warning('已有型号项目，请明确选择建档关联目标');return}if(unsaved.value||!filesComplete.value){ElMessage.warning(requiresCodes.value?'请保存修改、重新生成编码，并处理全部失败文件':'请保存修改并处理全部失败文件');return}if(options.value?.submitter?.departments.length&&!departmentId.value){ElMessage.warning('请明确选择真实钉钉部门');return}const auth=user.token;busy.value=true;try{await ElMessageBox.confirm(`将以 ${options.value?.submitter?.name||'已绑定的真实钉钉身份'} 发起正式开模审批，并产生审批待办。提交后表单冻结。`,'提交正式钉钉审批',{confirmButtonText:'确认提交',cancelButtonText:'继续填写'});checkSession(auth);const row=await api.submitMoldApplication(editing.value.applicationId,editing.value.version,departmentId.value);checkSession(auth);editing.value=row;workspace.changed();editor.value=false;emit('submitted',row.applicationId)}catch(e){if(auth===user.token&&e!=='cancel'&&e!=='close'){const row=await api.getMoldApplication(editing.value!.applicationId!).catch(()=>undefined);if(auth===user.token&&row&&row.status!=='draft'){editing.value=row;editor.value=false;workspace.changed();emit('progress',row.applicationId)}}throw e}finally{busy.value=false}}

let opening=0
async function open(row?:EditorDraft,context?:{projectInputUnsaved?:boolean}){++optionsEpoch;const epoch=++opening,auth=user.token;error.value='';const value=await api.getMoldOptions();if(epoch!==opening||auth!==user.token)return;if(busy.value||uploading.value)throw new Error('请等待当前操作完成');if(editor.value&&unsaved.value){await ElMessageBox.confirm('当前填写内容尚未保存，是否放弃并打开其他申请？','切换申请');if(epoch!==opening||auth!==user.token)return}if(!value.canCreate)throw new Error('当前账号无填写开模申请权限');options.value=value;if(row&&(row.status!=='draft'||row.canEditDraft===false)){if(row.applicationId)emit('progress',row.applicationId);return}projectInputUnsaved.value=!!context?.projectInputUnsaved;edit(row)}
watch(()=>user.token,()=>{invalidatePhoneRestore();++sourceFilesEpoch;sourceAttachments.value={};sourceAttachmentErrors.value={};++optionsEpoch;++opening;++compatibilityEpoch;++targetsEpoch;standardPhoneIds.value=[];standardPhone.value=undefined;compatibleMolds.value=[];reuseSetId.value=null;busy.value=false;editing.value=undefined;failedUploads.value=[];Object.keys(form).forEach(k=>delete form[k]);editor.value=false;options.value=undefined;error.value=''})
async function openResearch(row:api.MoldResearchContext,context?:{projectInputUnsaved?:boolean}){await open(row,context)}
defineExpose({open,openResearch})
</script>

<template>
    <el-drawer class="application-drawer" :style="{'--el-font-size-base':'12px'}" v-model="editor" :title="researchSource?'填写LEMOS开模申请':'填写开模申请'" size="min(980px,94vw)" :close-on-click-modal="false" :before-close="closeEditor" :close-on-press-escape="!busy&&!uploading" :show-close="!busy&&!uploading">
      <el-alert v-if="error" :title="error" type="error" :closable="false"/>
      <el-alert v-if="projectInputUnsaved" title="当前页有未保存修改；本次申请带入项目已保存的资料，未保存输入继续保留。" type="info" :closable="false"/>
      <el-alert v-if="researchSource?.restricted" title="来源新品项目受权限限制，请联系项目工程负责人查看或补充。" type="info" :closable="false"/>
      <section v-else-if="researchSource" class="research-source" aria-label="新品项目带入资料">
        <div class="tools"><strong>来自新品项目：{{researchSource.productName}}</strong><span>{{researchSource.productCode}}</span><el-button link @click="router.push({path:'/product-research',query:{productId:researchSource.projectId}})">查看来源项目</el-button></div>
        <el-alert v-if="existingApplicationNotice" :title="existingApplicationNotice" type="warning" :closable="false"/>
        <p>{{researchSource.phoneModelName||'标准手机待补充'}} · 负责人：{{researchSource.ownerName||'待分配'}}</p>
        <p v-if="researchSource.requirements" class="source-requirements">{{researchSource.requirements}}</p>
        <p v-if="researchSource.suppliersRestricted" class="source-warning">供应商资料受权限限制，请联系项目工程负责人补充。</p>
        <p v-else-if="researchSource.supplierPlanConfirmed===false" class="source-warning">供应商为项目当前方案，尚未正式确认；请在新品项目核对供方分工。</p>
        <p v-if="researchSource.referencesRestricted" class="source-warning">部分项目附件受权限限制，未带入当前申请；请联系有权限的工程人员补充。</p>
        <p v-for="(supplier,index) in researchSource.suppliers" :key="index">{{supplierRoles[supplier.role]||supplier.role}}：{{supplier.mode==='internal'?(supplier.internalName||'内部制作'):(supplier.supplierName||supplier.supplierCode)}}<span v-if="supplier.scope"> · {{supplier.scope}}</span><span v-if="supplier.basis||supplier.reason"> · {{supplier.basis||supplier.reason}}</span></p>
        <div class="research-source-files"><article v-for="file in researchSource.references" :key="`${file.type}:${file.id}`"><p>{{editing?.applicationId?'已带入':'保存草稿时带入'}}：{{file.name}}<span v-if="file.versionNo"> · {{file.versionNo}}</span></p><template v-if="editor&&!editing?.applicationId&&sourceAttachments[file.id]"><DocumentPreview v-if="['jpg','jpeg','png','webp'].includes(sourceAttachments[file.id]!.fileExt.toLowerCase())" :file="sourceAttachments[file.id]!" compact/><div class="tools"><el-button v-if="sourceAttachments[file.id]!.previewable" link @click="attempt(()=>sourceViewer.viewAttachment(sourceAttachments[file.id]!))">预览来源文件</el-button><el-button link @click="attempt(()=>sourceViewer.downloadFile(sourceAttachments[file.id]!))">下载来源文件</el-button></div></template><p v-else-if="sourceAttachmentErrors[file.id]" role="alert">{{sourceAttachmentErrors[file.id]}} <el-button link @click="loadSourceFiles(editing)">重试来源文件</el-button></p></article></div>
        <small>带入时间 {{researchSource.capturedAt}}。来源依据保留；申请中的补充填写及附件继续保存在同一草稿。</small>
      </section>
      <div v-if="editing&&!editing.applicationId&&'existingApplications' in editing&&editing.existingApplications?.length" class="tools" aria-label="项目原开模申请"><span>已有申请，可继续原记录：</span><el-button v-for="application in editing.existingApplications" :key="application.applicationId" link type="primary" @click="attempt(()=>openExisting(application.applicationId))">{{application.approvalNo||`申请 #${application.applicationId}`}} · {{application.model||'标准手机待补充'}}</el-button></div>
      <el-alert v-if="researchSubmission" title="新品研发审批：产品、手机及模具编码可待工程建档时确认，不作为本次送审前置。" type="info" :closable="false"><p v-if="filingMissing.length">建档待补：{{filingMissing.join('、')}}。审批不等于已建模具或可开工。</p></el-alert>
      <el-form label-position="top" class="application-form" :disabled="busy||uploading">
        <el-form-item label="开模产品" :required="true"><el-select v-model="productLineId" aria-label="开模产品" :disabled="!!researchSource" clearable filterable @change="chooseProduct"><el-option v-for="p in productChoices" :key="p.productId" :value="p.productId" :disabled="!eligibleProductIds.has(p.productId)" :label="productLabel(p)"/></el-select><small>在售产品及研发各阶段的新品可先填写草稿；正式提交前需补齐申请资料。</small><el-alert v-if="executionIssue" :title="executionIssue" type="warning" :closable="false"/><div v-if="productIdentityMissing" class="tools"><el-button v-if="canMaintainProductIdentity" link type="primary" :disabled="busy||uploading" @click="openProductIdentity">维护产品特定编码</el-button><small v-else>请联系有产品编码维护权限的工程人员补齐已确认编码。</small></div><el-button v-if="researchSource" link type="primary" :disabled="busy||uploading" @click="refreshOptions">刷新申请配置</el-button><template v-if="configurationMissing"><el-button v-if="options?.administrator" link type="primary" @click="openConfiguration">补充产品线配置</el-button><small v-else>请管理员在“开模申请进度 → 更多 → 产品线配置”补充映射；当前钉钉模板缺少对应 Tipo 时需先由审批管理员核对。</small></template></el-form-item>
        <el-form-item label="标准手机成员"><SharedCompatiblePhoneSelector v-model="standardPhoneIds" :multiple="false" :allow-manage="!!options?.administrator" @selected="chooseStandardPhone"/><small v-if="researchSubmission&&!standardPhone">标准手机可稍后关联；本次送审仍须如实填写下方Modelos型号或开模对象说明，不自动猜码或创建手机。</small><small v-else-if="researchSource&&!standardPhone">请选择本次实际开模的标准手机，可按品牌浏览全部型号；项目描述不会自动创建或确认机型。</small><small v-if="standardPhone">手机原编码 {{ standardPhone.phoneModelCode || '待分配' }}，不替换模具刻码。</small></el-form-item>
        <el-form-item v-if="tipoControl&&productLineId" label="审批类型（随产品匹配）" :required="tipoControl.required">
          <small v-if="automaticTipo" class="automatic-tipo" aria-label="自动匹配的审批类型">已按所选产品匹配：{{form.tipo}}</small>
          <el-select v-else-if="tipoChoices.length" v-model="form.tipo" clearable aria-label="tipo"><el-option v-for="tipo in tipoChoices" :key="tipo" :value="tipo" :label="tipoSelectable(tipo)?tipo:`${tipo} · 不可新申请`" :disabled="!tipoSelectable(tipo)"/></el-select>
          <small v-else>{{researchSubmission?'当前模板暂无允许的新品审批类型，请审批管理员核对原模板。':'补齐所选产品的审批映射后自动带出；当前可先保存草稿。'}}</small>
        </el-form-item>
<el-form-item v-for="c in inputControls" :key="c.key" :label="c.label" :required="c.required"><el-select v-if="c.options.length" v-model="form[c.key]" clearable :aria-label="c.key"><el-option v-for="v in c.options" :key="v" :value="v" :label="v"/></el-select><el-date-picker v-else-if="c.type==='DDDateField'" v-model="form[c.key]" value-format="YYYY-MM-DD" :aria-label="c.key"/><el-input v-else v-model="form[c.key]" :readonly="c.key==='model'&&!!standardPhone" :type="c.type==='TextareaField'?'textarea':'text'" :rows="3" :aria-label="c.key" :maxlength="c.type==='TextareaField'?4000:255"/></el-form-item>
        <el-form-item v-if="targets.existingApplications?.some(a=>a.applicationId!==editing?.applicationId)" label="已有进行中申请"><el-button v-for="application in targets.existingApplications?.filter(a=>a.applicationId!==editing?.applicationId)" :key="application.applicationId" size="small" @click="openExisting(application.applicationId)">继续已有申请 {{application.approvalNo||`#${application.applicationId}`}}</el-button></el-form-item>
        <el-form-item v-if="!researchSubmission" label="开模方式"><el-radio-group v-model="executionIntent" aria-label="开模方式"><el-radio value="new">新建模具主档</el-radio><el-radio value="new_set">已有主档新增套／重新开模</el-radio><el-radio v-if="editing?.reservedCompatibility" value="reuse">保留历史复用申请</el-radio></el-radio-group><small>已有可用模具请在模具详情确认共模。</small><el-checkbox v-if="executionIntent==='new'&&(targets.items.length||targets.existingApplications?.length||newApplication)" v-model="newApplication">明确另建不同模具主档，并填写原因</el-checkbox></el-form-item>
        <el-form-item v-if="!researchSubmission&&executionIntent==='new_set'" label="加开所属模具主档"><el-select v-model="targetItemId" filterable clearable aria-label="加开所属模具主档"><el-option v-for="item in targets.items" :key="item.itemId" :value="item.itemId" :label="`${item.moldName} · ${item.compatibleModels}`"/></el-select></el-form-item>
        <el-form-item v-if="!researchSubmission&&targets.projects.length" label="已有型号项目"><el-select v-model="targetProjectId" clearable aria-label="已有型号项目"><el-option v-for="project in targets.projects" :key="project.projectId" :value="project.projectId" :label="project.productName"/></el-select><small>请明确选择；审批同意后直接关联此项目。</small></el-form-item>

        <el-form-item v-if="!researchSubmission" label="新增套／重新开模原因"><el-input v-model="executionReason" type="textarea" :rows="3" maxlength="2000" placeholder="新增实物套或另建模具时填写原因"/></el-form-item>
        <el-form-item v-if="!researchSubmission" label="旧资料原编码核对"><PhoneCodeSelector v-model="phoneCodeItemId" :disabled="!!standardPhone" :members="currentPhoneCodes" aria-label="旧资料原编码核对"/><small>已有编码不因成员扩展改变；未分配的标准手机不自动编码。</small></el-form-item>
        <el-form-item v-if="editing?.reservedCompatibility&&compatibleMolds.length" label="保留历史已确认共模套"><el-select v-model="reuseSetId" clearable placeholder="须明确选择；不按名称自动复用"><el-option v-for="mold in compatibleMolds" :key="mold.moldSetId" :value="mold.moldSetId" :label="`${mold.moldName || mold.styleName} · 原刻码 ${mold.engravedCode || '待核对'} · ${mold.physicalCode}`"/></el-select><small v-if="reuseSelection">采用原 {{ reuseSelection.parts.map(part=>part.code).join(' / ') }}，不创建新的实物、编码或费用。</small></el-form-item>
      </el-form><el-form v-if="options?.submitter" label-position="top" :disabled="busy||uploading"><el-form-item label="实际钉钉发起人">{{ options.submitter.name }}（当前 PLM 账号绑定身份）</el-form-item><el-form-item v-if="options.submitter.departments.length" label="钉钉发起部门"><el-select v-model="departmentId" aria-label="钉钉发起部门"><el-option v-for="d in options.submitter.departments" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item></el-form><p>模具编码：{{ generated }}</p><div class="upload-grid"><label>关键图片<input aria-label="上传关键图片" type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="uploading||busy" @change="upload($event,'key_photo')"/></label><label>样板 / 测试图片<input aria-label="上传测试图片" type="file" accept="image/png,image/jpeg,image/webp" multiple :disabled="uploading||busy" @change="upload($event,'sample_photo')"/></label><label>其他附件<input aria-label="上传其他附件" type="file" multiple :disabled="uploading||busy" @change="upload($event,'attachment')"/></label></div><div v-if="editing?.applicationId&&editing.files?.length" class="application-files" aria-label="申请图片与附件"><MoldApplicationFile v-for="f in editing.files" :key="`${editing.applicationId}:${f.attachmentId}`" :application-id="editing.applicationId!" :file="f" :active="editor"/></div>
      <el-alert v-if="failedUploads.length" title="有文件上传失败，审批提交已暂停" type="error" :closable="false"><p v-for="pending in failedUploads" :key="pending.selectionId">{{ pending.file.name }} <el-button text :disabled="uploading" @click="attempt(()=>discardPending(pending.selectionId))">移除此选择</el-button></p><el-button :disabled="uploading" @click="attempt(uploadPending)">重试失败文件</el-button></el-alert>
      <p v-for="f in editing?.files?.filter(f=>f.downloadStatus==='pending_upload')" :key="f.attachmentId">{{ f.fileName }}：已登记但未归档，请重新选择此文件上传，或 <el-button text @click="attempt(()=>discardStored(f))">移除未上传选择</el-button></p>
      <template #footer><div class="tools"><el-button :disabled="busy||uploading" @click="attempt(save)">保存草稿</el-button><el-button v-if="requiresCodes" :disabled="busy||uploading||!!executionIssue" @click="attempt(reserve)">{{ reuseSelection?'确认复用原刻码':'生成 / 预留编码' }}</el-button><el-button type="primary" :disabled="!options?.canSubmit||!editing?.applicationId||editing.status!=='draft'||(requiresCodes&&!editing.generatedCodes)||unsaved||!filesComplete||uploading||busy||!!executionIssue||!!submissionMissing.length" @click="attempt(submit)">提交钉钉审批</el-button></div><small v-if="!options?.canSubmit">{{ options?.submissionBlockReason||'钉钉提交当前未向此账号开放' }}</small><small v-else-if="unsaved">{{requiresCodes?'有未保存修改，请先保存并重新核对编码':'有未保存修改，请先保存草稿'}}</small><small v-else-if="submissionMissing.length" role="alert">送审还缺：{{submissionMissing.join('、')}}</small></template>
    </el-drawer>
</template>
<style scoped>
.research-source{padding:10px 12px;margin-bottom:12px;background:var(--el-fill-color-light);border:1px solid var(--el-border-color-lighter);border-radius:4px;font-size:12px;overflow-wrap:anywhere}.research-source p{margin:5px 0;line-height:1.6}.source-requirements{white-space:pre-wrap}.source-warning{color:var(--el-color-warning-dark-2)}
.research-source-files{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:8px}.research-source-files>article{min-width:0}.research-source-files :deep(.document-preview--compact){margin:6px 0}.application-files{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,280px),1fr));gap:8px;margin-top:12px}
.application-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 16px}.application-form .el-select,.application-form .el-date-editor{width:100%}.tools{display:flex;gap:6px;flex-wrap:wrap}.tools .el-button+.el-button{margin-left:0}.upload-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.upload-grid label{padding:12px;border:1px dashed var(--el-border-color);font-size:12px}.upload-grid input{display:block;margin-top:10px;width:100%}small{font-size:12px;color:var(--el-text-color-secondary)}@media(max-width:800px){.application-form,.upload-grid{grid-template-columns:1fr}}
</style>
